 const t=tr[lang],rtl=lang==="ar",activeModule=modules.find(m=>m.id===page);
 const call=async(path:string,method="GET",body?:any)=>{const controller=new AbortController();const timer=window.setTimeout(()=>controller.abort(),20000);let res:Response;try{res=await fetch(API+path,{method,headers:{"Content-Type":"application/json",...(token?{Authorization:"Bearer "+token}:{})},...(body?{body:JSON.stringify(body)}:{}),signal:controller.signal});}catch(error:any){if(error?.name==="AbortError")throw new Error(lang==="ar"?"الخادم لم يستجب خلال 20 ثانية. تحقق من الاتصال وحاول مجدداً.":lang==="fr"?"Le serveur n’a pas répondu en 20 secondes. Vérifiez la connexion et réessayez.":"The server did not respond within 20 seconds. Check your connection and try again.");throw new Error(lang==="ar"?"تعذر الاتصال بالخادم. تحقق من الإنترنت.":lang==="fr"?"Connexion au serveur impossible. Vérifiez Internet.":"Could not connect to the server. Check your internet connection.");}finally{window.clearTimeout(timer);}const d=await res.json().catch(()=>({success:false,message:t.saveError}));if(d.message)d.message=localizeServerMessage(d.message,lang);if(!res.ok||d.success===false)throw new Error(d.message||t.saveError);return d;};
