 const deleteRecord=async(r:Rec)=>{if(r.id.startsWith("linked-debt-")){setMessage(lang==="ar"?"هذا الدين مرتبط بالفاتورة. عدّل الفاتورة لتغيير المبلغ أو التسديد.":lang==="fr"?"Cette dette est liée à la facture. Modifiez la facture pour changer le montant ou le paiement.":"This debt is linked to its invoice. Edit the invoice to change the amount or payment.");return;}if(!confirm(t.confirmDelete))return;try{if(!navigator.onLine){const q=JSON.parse(localStorage.getItem(queueKey())||"[]");if(r.id.startsWith("local-")){localStorage.setItem(queueKey(),JSON.stringify(q.filter((x:any)=>x.localId!==r.id&&x.id!==r.id)));}else{q.push({op:"delete",id:r.id});localStorage.setItem(queueKey(),JSON.stringify(q));}setRecords(old=>old.filter(x=>x.id!==r.id));}else{await call("/records/"+r.id,"DELETE");await load()}}catch(e:any){setMessage(e.message)}};
